CREATE TABLE Employees (
  id INT PRIMARY KEY,
  name VARCHAR(50),
  salary INT,
  department_id INT
);

SELECT product_id, name, price
FROM Products
WHERE price < 20;

SELECT user_id, name, mail
FROM Users
WHERE mail LIKE '%@leetcode.com';

SELECT id, name
FROM Employees
WHERE manager_id IS NULL;

SELECT (
  SELECT DISTINCT salary
  FROM Employee
  ORDER BY salary DESC
  LIMIT 1 OFFSET 1
) AS SecondHighestSalary;

SELECT name, salary
FROM Employees
ORDER BY salary DESC, name ASC;

SELECT (
  SELECT DISTINCT salary
  FROM Employee
  ORDER BY salary DESC
  LIMIT 1 OFFSET 1
) AS SecondHighestSalary;

SELECT IFNULL(SUM(price * units), 0)                    AS revenue,
       IFNULL(ROUND(SUM(price * units) / SUM(units), 2), 0) AS avg_price
FROM Sales;

SELECT COUNT(*)                                        AS total_trips,
       SUM(CASE WHEN status <> 'completed' THEN 1 ELSE 0 END) AS cancelled_trips
FROM Trips;

SELECT department_id, COUNT(*) AS headcount
FROM Employees
GROUP BY department_id;

SELECT product_id, region, SUM(units) AS units_sold
FROM Sales
GROUP BY product_id, region;

SELECT name, salary
FROM Employees
WHERE salary > (SELECT AVG(salary) FROM Employees);

SELECT name
FROM Customers
WHERE id IN (SELECT customerId FROM Orders);

SELECT MAX(salary) AS SecondHighestSalary
FROM Employee
WHERE salary < (SELECT MAX(salary) FROM Employee);

WITH RECURSIVE seq AS (
    SELECT 1 AS n
    UNION ALL
    SELECT n + 1 FROM seq WHERE n < 10
)
SELECT n FROM seq;

SELECT name, salary,
       ROW_NUMBER() OVER (ORDER BY salary DESC) AS pos
FROM Employees;

SELECT recordDate, temperature,
       LAG(temperature) OVER (ORDER BY recordDate) AS prev_temperature
FROM Weather;

SELECT orderDate, amount,
       SUM(amount) OVER (
           ORDER BY orderDate
           ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS running_total
FROM Orders;

SELECT tweet_id
FROM Tweets
WHERE CHAR_LENGTH(content) > 15;

SELECT user_id, name, mail
FROM Users
WHERE mail REGEXP '^[a-zA-Z][a-zA-Z0-9_.-]*@leetcode\\.com$';
